def rain(x,y,w,h):
 s=f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="url(#window)"/>'
 for _ in range(75):
  a=random.randint(x+5,x+w-5);b=random.randint(y+5,y+h-40)
  s+=f'<path d="M{a} {b}l-5 {random.randint(8,35)}" stroke="#b7cfd1" stroke-opacity=".18"/>'
 for _ in range(18):
  a=random.randint(x,x+w-25);b=y+h-random.randint(30,int(h*.55))
  s+=f'<rect x="{a}" y="{b}" width="{random.randint(14,45)}" height="{y+h-b}" fill="#142c38" opacity=".7"/>'
 return s+f'<path d="M{x+w/2} {y}v{h} M{x} {y+h*.56}h{w}" stroke="#0c1b26" stroke-width="13"/>'
